1	import React, { useState } from 'react';
2	import type { Meta, StoryObj } from '@storybook/react-webpack5';
3	import { chakra } from '@chakra-ui/react';
4	import { expect, userEvent, waitForElementToBeRemoved, within } from 'storybook/test';
5	import { ZimmDrawer } from './index';
6	import type { ZimmDrawerSize } from './index';
7	
8	const meta: Meta<typeof ZimmDrawer> = {
9	  title: 'Elements/ZimmDrawer',
10	  component: ZimmDrawer,
11	};
12	export default meta;
13	type Story = StoryObj<typeof ZimmDrawer>;
14	
15	/**
16	 * Generic chrome only — no tab/header content here (see Commerce/ZimmPdpDrawer for a real
17	 * consumer). Proves the shell renders with the expected dialog semantics at each size variant.
18	 */
19	// Named component rather than an inline `render: () => { useState(...) }` — see zimmModal's
20	// story for why a lowercase `render` can't call hooks directly.
21	const OpenDrawerExample = ({ size }: { size: ZimmDrawerSize }) => {
22	  const [isOpen, setIsOpen] = useState(true);
23	  return (
24	    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} aria-label="Example drawer">
25	      <chakra.p padding="var(--zimm-scale-xl)">Generic ZimmDrawer chrome with arbitrary children.</chakra.p>
26	    </ZimmDrawer>
27	  );
28	};
29	
30	export const Large: Story = {
31	  render: () => <OpenDrawerExample size="large" />,
32	  play: async () => {
33	    // Portal renders outside canvasElement — testing.md §Layer-2 exception. Chakra's Drawer is
34	    // built on its Modal primitive, which renders DrawerContent via a Portal by default, so
35	    // within(canvasElement) can't reach it.
36	    const doc = within(document.body);
37	    const dialog = await doc.findByRole('dialog');
38	    await expect(dialog).toBeInTheDocument();
39	    await expect(dialog).toHaveAttribute('aria-label', 'Example drawer');
40	  },
41	};
42	
43	export const Tablet: Story = {
44	  render: () => <OpenDrawerExample size="tablet" />,
45	};
46	
47	export const Small: Story = {
48	  render: () => <OpenDrawerExample size="small" />,
49	};
50	
51	export const XLarge: Story = {
52	  render: () => <OpenDrawerExample size="xLarge" />,
53	};
54	
55	export const Mobile: Story = {
56	  render: () => <OpenDrawerExample size="mobile" />,
57	};
58	
59	export const Prompt: Story = {
60	  render: () => <OpenDrawerExample size="prompt" />,
61	};
62	
63	export const CloseButtonClosesTheDrawer: Story = {
64	  render: () => <OpenDrawerExample size="large" />,
65	  play: async () => {
66	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
67	    const doc = within(document.body);
68	    const dialog = await doc.findByRole('dialog');
69	    await expect(dialog).toBeInTheDocument();
70	
71	    await userEvent.click(doc.getByRole('button', { name: /close/i }));
72	
73	    // Chakra's Drawer plays a slide-out exit transition (framer-motion) before AnimatePresence
74	    // actually unmounts the dialog node — an immediate `queryByRole('dialog')` assertion here
75	    // catches it mid-animation, still present with a near-100% translateX. Wait for the real
76	    // removal instead of asserting the instant after the click.
77	    await waitForElementToBeRemoved(dialog);
78	  },
79	};
80	
81	// --- Title header variants ---
82	
83	const WithTitleExample = ({ size, titleStyle }: { size: ZimmDrawerSize; titleStyle?: 'large' | 'small' }) => {
84	  const [isOpen, setIsOpen] = useState(true);
85	  return (
86	    <ZimmDrawer isOpen={isOpen} onClose={() => setIsOpen(false)} size={size} title="SIGN IN" titleStyle={titleStyle}>
87	      <chakra.p padding="var(--zimm-scale-xl)">Drawer body content.</chakra.p>
88	    </ZimmDrawer>
89	  );
90	};
91	
92	/** Inline header row: title on the left, close button on the right — Figma Heading (Large) style. */
93	export const WithTitleLarge: Story = {
94	  render: () => <WithTitleExample size="large" titleStyle="large" />,
95	  play: async () => {
96	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
97	    const doc = within(document.body);
98	    // Queried by computed accessible name rather than a specific aria-* attribute: ZimmDrawer's
99	    // custom ZimmDrawerContent sets aria-labelledby to the visible title span's id for the title
100	    // case (see index.tsx's own comment on why aria-label isn't needed here) — this asserts the
101	    // real outcome without pinning the test to which mechanism produces it.
102	    const dialog = await doc.findByRole('dialog', { name: 'SIGN IN' });
103	    await expect(dialog).toBeInTheDocument();
104	    await expect(doc.getByText('SIGN IN')).toBeInTheDocument();
105	  },
106	};
107	
108	/** Inline header with body2Strong (14px bold) title — Figma Heading (Small) / textStyle="body2Strong". */
109	export const WithTitleSmallStyle: Story = {
110	  render: () => <WithTitleExample size="large" titleStyle="small" />,
111	};
112	
113	/** Small-width drawer with inline title header. */
114	export const WithTitleSmallDrawer: Story = {
115	  render: () => <WithTitleExample size="small" titleStyle="large" />,
116	};
117	
118	/** Title close button dismisses the drawer. */
119	export const TitleCloseButtonClosesTheDrawer: Story = {
120	  render: () => <WithTitleExample size="large" />,
121	  play: async () => {
122	    // Portal renders outside canvasElement — testing.md §Layer-2 exception (see Large's play).
123	    const doc = within(document.body);
124	    const dialog = await doc.findByRole('dialog');
125	    await expect(dialog).toBeInTheDocument();
126	
127	    await userEvent.click(doc.getByRole('button', { name: /close/i }));
128	
129	    await waitForElementToBeRemoved(dialog);
130	  },
131	};
132	
133	// --- boxedHeader (SFCC-831) ---
134	
135	/**
136	 * `labelledBy` + `boxedHeader` — the real header row `title` gets (title span occupies its flex
137	 * space, close button lands in the same right-aligned spot), but the span is empty: no visible
138	 * title text. The drawer's accessible name comes from the external `<h2>` below, referenced by
139	 * `labelledBy`, not from the header row itself. `size="prompt"` matches the real consumer
140	 * (ZimmCountryLanguageMismatch, SFCC-831) — first visual proof of this combination anywhere;
141	 * component-level index.test.tsx proves the type/accessibility contract, this proves the render.
142	 */
143	const WithBoxedHeaderExample = () => {
144	  const [isOpen, setIsOpen] = useState(true);
145	  return (
