import { chromium } from '@playwright/test';

const BASE = 'http://localhost:6006/iframe.html?viewMode=story&id=';

const targets = [
  { id: 'layout-zimmcountrylanguagemismatch--location', widths: [390, 834, 1440] },
  { id: 'elements-zimmdrawer--with-title-large', widths: [390] },
  { id: 'elements-zimmdrawer--with-title-small-drawer', widths: [390] },
  { id: 'elements-zimmdrawer--with-boxed-header', widths: [390] },
];

const browser = await chromium.launch();
const page = await browser.newPage();

for (const t of targets) {
  for (const width of t.widths) {
    await page.setViewportSize({ width, height: 900 });
    await page.goto(BASE + t.id, { waitUntil: 'networkidle' });
    // Wait for the dialog to be present
    await page.waitForSelector('[role="dialog"]', { timeout: 10000 });

    const result = await page.evaluate(() => {
      const closeButton = [...document.querySelectorAll('button')].find((b) =>
        (b.getAttribute('aria-label') || '').toLowerCase().includes('close'),
      );
      if (!closeButton) return { error: 'no close button found' };

      // boxed header: closeButton -> headerCloseButton div -> headerBox div
      // floating: closeButton -> closeButton box (position: absolute)
      const level1 = closeButton.parentElement;
      const level2 = level1 ? level1.parentElement : null;

      const rectOf = (el) => (el ? el.getBoundingClientRect() : null);
      const styleOf = (el) => (el ? getComputedStyle(el) : null);

      const level1Rect = rectOf(level1);
      const level2Rect = rectOf(level2);
      const level1Position = styleOf(level1)?.position;

      return {
        closeButtonRect: rectOf(closeButton),
        level1: { tag: level1?.tagName, position: level1Position, rect: level1Rect, childCount: level1?.children.length },
        level2: { tag: level2?.tagName, rect: level2Rect, childCount: level2?.children.length },
      };
    });

    console.log(JSON.stringify({ story: t.id, width, result }, null, 0));
  }
}

await browser.close();
